#!/usr/bin/env bash
# Agent Bridge — standalone one-shot installer (single file, no git clone needed).
# Usage: curl -L -o agent-bridge-install.sh <release-url> && chmod +x agent-bridge-install.sh && ./agent-bridge-install.sh
# Env overrides: BIND_IP, PORT, BRIDGE_API_TOKEN, CLOUD_*, INSTALL_OLLAMA=0, PULL_MODEL, SERVICE_NAME
set -euo pipefail
command -v base64 >/dev/null || { echo "base64 is required" >&2; exit 1; }
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
echo "[*] Extracting embedded Agent Bridge files..."
sed -n '/^__AGENT_BRIDGE_BUNDLE__$/,$p' "$0" | tail -n +2 | base64 -d | tar xz -C "$TMP"
cd "$TMP"
chmod +x install.sh enable_server_sudo.sh smoke_test.py
echo "[*] Running installer from $TMP"
./install.sh "$@"
